/bin/bash -lc "mkdir -p /workspace/galaxy_scripts
cat > /workspace/galaxy_scripts/coord_diagnostic.py <<'PY'
import csv, json, sys, time, urllib.parse, urllib.request

inp, outp = sys.argv[1], sys.argv[2]
rows = []
with open(inp) as f:
    r = csv.DictReader(f, delimiter='\\t')
    for row in r:
        rows.append(row)

# Try starts as UCSC 0-based half-open [start,start+len(ref)) and 1-based SNP position start -> [start-1,start-1+len(ref)).
# Also include +1/-1 shifts to catch off-by-one conventions.
configs = []
for genome in ['hg19','hg38']:
    for label, shift in [('as_0based', 0), ('as_1based', -1), ('plus1', 1), ('minus1', -1)]:
        # plus/minus labels are relative to zero-based interpretation; as_1based duplicates minus1 but is named for clarity.
        if (genome, label, shift) not in configs:
            configs.append((genome, label, shift))

def fetch_seq(genome, chrom, start0, end0):
    params = urllib.parse.urlencode({'genome': genome, 'chrom': chrom, 'start': start0, 'end': end0})
    url = 'https://api.genome.ucsc.edu/getData/sequence?' + params
    last = None
    for attempt in range(5):
        try:
            with urllib.request.urlopen(url, timeout=30) as resp:
                data = json.loads(resp.read().decode('utf-8'))
            if 'dna' not in data:
                raise RuntimeError(str(data)[:300])
            return data['dna'].upper()
        except Exception as e:
            last = e
            time.sleep(1 + attempt)
    raise RuntimeError('UCSC fetch failed %s:%s-%s %s: %r' % (chrom,start0,end0,genome,last))

summary = []
examples = []
for genome, label, shift in configs:
    matches = 0; mismatches = 0; errors = 0
    for row in rows:
        ref = row['ref'].upper()
        start0 = int(row['start']) + shift
        try:
            seq = fetch_seq(genome, row['chr'], start0, start0 + len(ref))
            if seq == ref:
                matches += 1
            else:
                mismatches += 1
                if len(examples) < 40:
                    examples.append([genome, label, row['chr'], row['start'], ref, seq])
        except Exception as e:
            errors += 1
            if len(examples) < 40:
                examples.append([genome, label, row['chr'], row['start'], ref, 'ERROR:'+repr(e)])
    summary.append([genome, label, shift, matches, mismatches, errors, len(rows), matches/len(rows)])

with open(outp, 'w', newline='') as f:
    w = csv.writer(f, delimiter='\\t')
    w.writerow(['genome','interpretation','start_shift_to_0based','matches','mismatches','errors','total','match_rate'])
    w.writerows(summary)
    w.writerow([])
    w.writerow(['example_genome','example_interpretation','chr','start','input_ref','fetched_ref'])
    w.writerows(examples)
PY"

