item.command:
/bin/bash -lc "python3 - <<'PY'
import csv,json,urllib.parse,urllib.request,time
rows=list(csv.DictReader(open('inputs/retina.score.snps.q1.tsv'), delimiter='\\t'))
cache={}
def fetch(genome, chrom, s, e):
    key=(genome,chrom,s,e)
    if key in cache: return cache[key]
    url='https://api.genome.ucsc.edu/getData/sequence?'+urllib.parse.urlencode({'genome':genome,'chrom':chrom,'start':s,'end':e})
    for i in range(4):
        try:
            data=json.loads(urllib.request.urlopen(url,timeout=20).read().decode())
            dna=data['dna'].upper(); cache[key]=dna; return dna
        except Exception as ex:
            last=ex; time.sleep(1+i)
    raise last
for genome in ['hg19','hg38']:
  for label,shift in [('zero',0),('one',-1),('plus1',1)]:
    m=0; ex=[]
    for r in rows:
      ref=r['ref'].upper(); s=int(r['start'])+shift
      dna=fetch(genome,r['chr'],s,s+len(ref))
      if dna==ref: m+=1
      elif len(ex)<3: ex.append((r['chr'],r['start'],ref,dna))
    print(genome,label,m,len(rows),m/len(rows),ex)
PY"

